CKMMWY(const amrex::Real y[], amrex::Real& wtm)
{
  amrex::Real YOW = 0;

  for (int i = 0; i < 32; i++) {
    YOW += y[i] * imw(i);
  }

  wtm = 1.0 / YOW;
}

