  CW += c[24] * 2.8053999999999998e+01; // C2H4
  CW += c[25] * 2.9061999999999998e+01; // C2H5
  CW += c[26] * 3.0070000000000000e+01; // C2H6
  CW += c[27] * 4.1028999999999996e+01; // HCCO
  CW += c[28] * 4.2036999999999999e+01; // CH2CO
  CW += c[29] * 4.2036999999999999e+01; // HCCOH
  CW += c[30] * 2.8013999999999999e+01; // N2
  CW += c[31] * 3.9950000000000003e+01; // AR
  // Now compute conversion
  amrex::Real CWinv = 1.0 / CW;
  y[0] = c[0] * 2.0160000000000000e+00 * CWinv;
  y[1] = c[1] * 1.0080000000000000e+00 * CWinv;
  y[2] = c[2] * 1.5999000000000001e+01 * CWinv;
  y[3] = c[3] * 3.1998000000000001e+01 * CWinv;
