  y[7] = c[7] * 3.4014000000000003e+01 * CWinv;
  y[8] = c[8] * 1.2010999999999999e+01 * CWinv;
  y[9] = c[9] * 1.3018999999999998e+01 * CWinv;
  y[10] = c[10] * 1.4026999999999999e+01 * CWinv;
  y[11] = c[11] * 1.4026999999999999e+01 * CWinv;
  y[12] = c[12] * 1.5035000000000000e+01 * CWinv;
  y[13] = c[13] * 1.6042999999999999e+01 * CWinv;
  y[14] = c[14] * 2.8009999999999998e+01 * CWinv;
  y[15] = c[15] * 4.4009000000000000e+01 * CWinv;
  y[16] = c[16] * 2.9018000000000001e+01 * CWinv;
  y[17] = c[17] * 3.0026000000000000e+01 * CWinv;
  y[18] = c[18] * 3.1033999999999999e+01 * CWinv;
  y[19] = c[19] * 3.1033999999999999e+01 * CWinv;
  y[20] = c[20] * 3.2042000000000002e+01 * CWinv;
  y[21] = c[21] * 2.5029999999999998e+01 * CWinv;
  y[22] = c[22] * 2.6037999999999997e+01 * CWinv;
  y[23] = c[23] * 2.7045999999999999e+01 * CWinv;
  y[24] = c[24] * 2.8053999999999998e+01 * CWinv;
  y[25] = c[25] * 2.9061999999999998e+01 * CWinv;
  y[26] = c[26] * 3.0070000000000000e+01 * CWinv;
  y[27] = c[27] * 4.1028999999999996e+01 * CWinv;
  y[28] = c[28] * 4.2036999999999999e+01 * CWinv;
  y[29] = c[29] * 4.2036999999999999e+01 * CWinv;
  y[30] = c[30] * 2.8013999999999999e+01 * CWinv;
