  // reaction 133: CH + HCCO <=> C2H2 + CO
  qf[139] = sc[9] * sc[27];
  qr[139] = sc[14] * sc[22];

  // reaction 134: CH2 + O2 <=> HCO + OH
  qf[140] = sc[3] * sc[10];
  qr[140] = sc[4] * sc[16];

  // reaction 135: CH2 + H2 <=> CH3 + H
  qf[141] = sc[0] * sc[10];
  qr[141] = sc[1] * sc[12];

  // reaction 136: 2 CH2 <=> C2H2 + H2
  qf[142] = (sc[10] * sc[10]);
  qr[142] = sc[0] * sc[22];

  // reaction 137: CH2 + CH3 <=> C2H4 + H
  qf[143] = sc[10] * sc[12];
  qr[143] = sc[1] * sc[24];

  // reaction 138: CH2 + CH4 <=> 2 CH3
  qf[144] = sc[10] * sc[13];
  qr[144] = (sc[12] * sc[12]);

  // reaction 140: CH2 + HCCO <=> C2H3 + CO
  qf[145] = sc[10] * sc[27];
  qr[145] = sc[14] * sc[23];

  // reaction 141: CH2(S) + N2 <=> CH2 + N2
  qf[146] = sc[11] * sc[30];
