  // reaction 159: CH3 + HCO <=> CH4 + CO
  qf[162] = sc[12] * sc[16];
  qr[162] = sc[13] * sc[14];

  // reaction 160: CH2O + CH3 <=> CH4 + HCO
  qf[163] = sc[12] * sc[17];
  qr[163] = sc[13] * sc[16];

  // reaction 161: CH3 + CH3OH <=> CH2OH + CH4
  qf[164] = sc[12] * sc[20];
  qr[164] = sc[13] * sc[18];

  // reaction 162: CH3 + CH3OH <=> CH3O + CH4
