  // reaction 168: CH2OH + O2 <=> CH2O + HO2
  qf[169] = sc[3] * sc[18];
  qr[169] = sc[6] * sc[17];

  // reaction 169: CH3O + O2 <=> CH2O + HO2
  qf[170] = sc[3] * sc[19];
  qr[170] = sc[6] * sc[17];

  // reaction 170: C2H + O2 <=> CO + HCO
