  qr[37] *= k_f * (kc_fast ? (inv_ge[4] * inv_ge[6] * ge[7] * ge[2])
                           : exp(-(g_RT[2] - g_RT[4] - g_RT[6] + g_RT[7])));
  // reaction 5:  CH + O <=> CO + H
  k_f = 57000000;
  qf[38] *= k_f;
  qr[38] *= k_f * (kc_fast ? (inv_ge[14] * inv_ge[1] * ge[2] * ge[9])
                           : exp(-(-g_RT[1] + g_RT[2] + g_RT[9] - g_RT[14])));
  // reaction 6:  CH2 + O <=> H + HCO
  k_f = 80000000;
  qf[39] *= k_f;
  qr[39] *= k_f * (kc_fast ? (inv_ge[16] * inv_ge[1] * ge[2] * ge[10])
                           : exp(-(-g_RT[1] + g_RT[2] + g_RT[10] - g_RT[16])));
  // reaction 7:  CH2(S) + O <=> CO + H2
  k_f = 15000000;
  qf[40] *= k_f;
  qr[40] *= k_f * (kc_fast ? (inv_ge[0] * inv_ge[14] * ge[2] * ge[11])
                           : exp(-(-g_RT[0] + g_RT[2] + g_RT[11] - g_RT[14])));
  // reaction 8:  CH2(S) + O <=> H + HCO
  k_f = 15000000;
  qf[41] *= k_f;
  qr[41] *= k_f * (kc_fast ? (inv_ge[16] * inv_ge[1] * ge[2] * ge[11])
                           : exp(-(-g_RT[1] + g_RT[2] + g_RT[11] - g_RT[16])));
  // reaction 9:  CH3 + O <=> CH2O + H
  k_f = 84300000;
  qf[42] *= k_f;
  qr[42] *= k_f * (kc_fast ? (ge[12] * inv_ge[1] * inv_ge[17] * ge[2])
                           : exp(-(-g_RT[1] + g_RT[2] + g_RT[12] - g_RT[17])));
  // reaction 10:  CH4 + O <=> CH3 + OH
  k_f = 1020 * exp((1.5) * logT - (4327.66332592059) * invT);
  qf[43] *= k_f;
  qr[43] *= k_f * (kc_fast ? (inv_ge[4] * ge[13] * ge[2] * inv_ge[12])
                           : exp(-(g_RT[2] - g_RT[4] - g_RT[12] + g_RT[13])));
  // reaction 11:  CO + O + M <=> CO2 + M
  k_f = 602 * exp(-(1509.64999741416) * invT);
  Corr = mixture + sc[0] + (5) * sc[3] + (5) * sc[5] + sc[13] + (0.5) * sc[14] +
         (2.5) * sc[15] + (2) * sc[26] + (-0.5) * sc[31];
  qf[22] *= Corr * k_f;
