    const amrex::Real qr = Corr * k_f *
                           (kc_fast ? (ge[12] * inv_ge[13] * ge[1])
                                    : exp(-(g_RT[1] + g_RT[12] - g_RT[13]))) *
                           (refC) * (sc[13]);
