    dqdci = (2 - 1) * q_nocor;
    J[2] -= dqdci;  // dwdot[O]/d[H2]
    J[14] -= dqdci; // dwdot[CO]/d[H2]
    J[15] += dqdci; // dwdot[CO2]/d[H2]
