    J[463] -= dqdci; // dwdot[H]/d[CO]
    J[465] -= dqdci; // dwdot[O2]/d[CO]
    J[468] += dqdci; // dwdot[HO2]/d[CO]
    // d()/d[CO2]
    dqdci = (1.5 - 1) * q_nocor;
    J[496] -= dqdci; // dwdot[H]/d[CO2]
    J[498] -= dqdci; // dwdot[O2]/d[CO2]
    J[501] += dqdci; // dwdot[HO2]/d[CO2]
