  J[1057] -= dqdT; // dwdot[H]/dT
  J[1059] -= dqdT; // dwdot[O2]/dT
  J[1062] += dqdT; // dwdot[HO2]/dT

  // reaction 33: H + O2 + O2 <=> HO2 + O2
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[1] * (sc[3] * sc[3]);
  k_f = 300000000 * exp(-1.72 * logT);
  dlnkfdT = -1.72 * invT;
  // reverse
  phi_r = sc[3] * sc[6];
  Kc = refCinv * (kc_fast ? (inv_ge[3] * ge[6] * inv_ge[1])
                          : exp(g_RT[1] + g_RT[3] - g_RT[6]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(h_RT[1] + 2.000000 * h_RT[3]) + (h_RT[3] + h_RT[6]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
