  J[102] -= dqdci; // dwdot[O2]/d[O2]
  J[105] += dqdci; // dwdot[HO2]/d[O2]
  // d()/d[H2O]
  dqdci = +k_f * sc[1] * sc[3] - k_r * sc[6];
