  dqdci = +k_f * sc[3] * sc[31];
  J[34] -= dqdci; // dwdot[H]/d[H]
  J[36] -= dqdci; // dwdot[O2]/d[H]
  J[39] += dqdci; // dwdot[HO2]/d[H]
