  J[201] -= dqdci; // dwdot[O2]/d[HO2]
  J[204] += dqdci; // dwdot[HO2]/d[HO2]
  // d()/d[AR]
  dqdci = +k_f * sc[1] * sc[3] - k_r * sc[6];
  J[1024] -= dqdci; // dwdot[H]/d[AR]
  J[1026] -= dqdci; // dwdot[O2]/d[AR]
  J[1029] += dqdci; // dwdot[HO2]/d[AR]
  // d()/dT
