  Kc = refCinv * (kc_fast ? (ge[0] * inv_ge[1] * inv_ge[1])
                          : exp(-g_RT[0] + 2.000000 * g_RT[1]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(2.000000 * h_RT[1]) + (h_RT[0]) + 1.000000);
